recipes.code:
{
  "inputs": [
    {
      "id": "docparse-api-key",
      "type": "promptString",
      "description": "AILANG Parse API key (dp_...). Optional — the bridge auto-loads keys saved at ~/.config/ailang-parse/credentials.json. Get one from https://www.sunholo.com/ailang-parse/",
      "password": true
    }
  ],
  "servers": {
    "parse": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@ailang/parse@0.8.0",
        "mcp"
      ],
      "env": {
        "DOCPARSE_API_KEY": "${input:docparse-api-key}",
        "AILANG_PARSE_MCP_URL": "<ailang-parse-mcp-url>"
      }
    }
  }
}
